
@layer components{.social-share-button{align-items:center;display:flex;gap:.5em;text-decoration:none;width:-moz-min-content;width:min-content}.social-share-button__icon{font-size:1.5em}.social-share-button--styled{--color-hover:color-mix(in srgb,var(--color-brand),#000 15%);background-color:var(--color-brand);border-radius:.25rem;color:#fff;font-size:.875rem;line-height:normal;padding:.5rem;transition:background-color .25s ease-out}.social-share-button--styled:hover{background-color:var(--color-hover)}.social-share-button--styled:focus-visible{outline:2px solid var(--color-brand);outline-offset:2px}.social-share-button--styled .social-share-button__label{padding:0 .5rem;white-space:nowrap}}
